9	/**
10	 * The consolidated duplicate check, rejecting a create with 409 in either of two ways:
11	 *
12	 * <ul>
13	 * <li><b>Full-identity duplicate</b> — the whole {@code identityKey} (see {@link OwnerIdentity},
14	 * {@code normalizedTelephone|email|householdId}) equals an existing owner's. Because the telephone
15	 * is part of the key, two members of the same household with different telephones have different
16	 * keys; only an exact whole-key match collides. This always applies, even when
17	 * {@code sharesHousehold} is set.</li>
18	 * <li><b>Household duplicate</b> — the new owner's computed {@code householdId} (keyed on
19	 * lastName + postcode; see {@link AssignHousehold}) already identifies an existing owner, i.e. a
20	 * second owner sharing lastName and postcode. This is blocked <em>unless</em> the request opts in
21	 * with {@code sharesHousehold}, in which case the new owner is created as a declared household
22	 * member.</li>
23	 * </ul>
24	 *
25	 * <p>Runs after {@link AssignHousehold} so the new owner's {@code householdId} is set before it is
26	 * compared. The new owner is not yet saved, so it is not among the existing owners compared here.
27	 */
28	public class EnsureUniqueIdentity {
29	
30	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
31	            throws DuplicateIdentityException {
32	        String identityKey = OwnerIdentity.of(owner);
33	        String householdId = owner.getHouseholdId();
34	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (identityKey.equals(OwnerIdentity.of(existing))) {
37	                throw new DuplicateIdentityException(identityKey);
38	            }
39	            if (!sharesHousehold && householdId != null
40	                    && householdId.equals(existing.getHouseholdId())) {
41	                throw new DuplicateIdentityException(identityKey);
42	            }
43	        }
44	    }
45	}
